 @DynamicPropertySource static void props(DynamicPropertyRegistry r){var e=WalletDevelopmentGuard.settings();r.add("spring.datasource.url",WalletDevelopmentGuard::url);r.add("spring.datasource.username",()->e.get("DB_USERNAME"));r.add("spring.datasource.password",()->e.get("DB_PASSWORD"));r.add("spring.data.redis.password",()->e.get("REDIS_PASSWORD"));}
 @Autowired CmsService service;@Autowired JdbcTemplate jdbc;@Autowired MockMvc mvc;@Autowired ApplicationContext context;String run="cms"+UUID.randomUUID().toString().replace("-","").substring(0,8);Map<String,Long>users=new HashMap<>();Long page;Media image,model;Scene internal;
 long user(String role){jdbc.update("INSERT INTO sys_user(username,password,real_name,email,status) VALUES(?,?,'CMS Test',?,1)",run+role,"x",run+role+"@test.invalid");long id=jdbc.queryForObject("SELECT id FROM sys_user WHERE username=?",Long.class,run+role);jdbc.update("INSERT INTO sys_user_role(user_id,role_id) SELECT ?,id FROM sys_role WHERE role_code=?",id,role);users.put(role,id);return id;}UsernamePasswordAuthenticationToken auth(String role){String actual=role.equals("ANON")?"":role;var a=new UsernamePasswordAuthenticationToken("cms",null,actual.isEmpty()?List.of():List.of(new SimpleGrantedAuthority("ROLE_"+actual),new SimpleGrantedAuthority("SURFACE_"+("CUSTOMER".equals(actual)?"CUSTOMER_PUBLIC":"PMS_INTERNAL"))));if(!actual.isEmpty())a.setDetails(users.get(actual));return a;}void as(String role){SecurityContextHolder.getContext().setAuthentication(auth(role));}
