 @Test@Order(1)void migrationSecurityAndDraftPublicationIsolation()throws Exception{assertEquals("62",jdbc.queryForObject("SELECT version FROM flyway_schema_history WHERE success=1 ORDER BY installed_rank DESC LIMIT 1",String.class));assertTrue(context.getBeansOfType(org.springframework.security.provisioning.InMemoryUserDetailsManager.class).isEmpty());as("MANAGER");var created=service.create(page("zh-CN","Draft title"));page=created.getId();service.section(page,section("v1"),null);mvc.perform(get("/api/public/site/pages/{slug}",run)).andExpect(status().isNotFound());as("MANAGER");service.publish(page);mvc.perform(get("/api/public/site/pages/{slug}",run)).andExpect(status().isOk()).andExpect(jsonPath("$.data.title").value("Draft title")).andExpect(jsonPath("$.data.sections[0].payload").exists());as("MANAGER");var e=new CmsRequests.PageEdit();e.setTitle("Draft v2");e.setExpectedVersion(2);service.edit(page,e);mvc.perform(get("/api/public/site/pages/{slug}",run)).andExpect(status().isOk()).andExpect(jsonPath("$.data.title").value("Draft title"));as("MANAGER");service.publish(page);mvc.perform(get("/api/public/site/pages/{slug}",run)).andExpect(status().isOk()).andExpect(jsonPath("$.data.title").value("Draft v2"));}
 @Test@Order(2)void roleBoundarySurfaceAndPagination()throws Exception{for(String role:List.of("CUSTOMER","STAFF","HR_ADMIN","FINANCE"))mvc.perform(get("/api/admin/cms/pages").with(authentication(auth(role)))).andExpect(status().isForbidden());for(String role:List.of("MANAGER","OWNER","SUPER_ADMIN"))mvc.perform(get("/api/admin/cms/pages?page=1&pageSize=20").with(authentication(auth(role)))).andExpect(status().isOk()).andExpect(jsonPath("$.data.items").isArray());mvc.perform(get("/api/admin/cms/pages?pageSize=101").with(authentication(auth("MANAGER")))).andExpect(status().isBadRequest());mvc.perform(get("/api/admin/cms/pages")).andExpect(status().isUnauthorized());mvc.perform(get("/api/admin/cms/pages").header("Authorization","Basic dXNlcjpwYXNzd29yZA==")).andExpect(status().isUnauthorized());mvc.perform(post("/login")).andExpect(status().isUnauthorized());}
 @Test@Order(3)void mediaValidationPublishedProtectionAndSceneBoundary()throws Exception{as("MANAGER");assertThrows(com.johnny.hotel.exception.BusinessException.class,()->service.upload("IMAGE",new MockMultipartFile("file","../x.jpg","image/jpeg",new byte[]{1})));assertThrows(com.johnny.hotel.exception.BusinessException.class,()->service.upload("IMAGE",new MockMultipartFile("file","x.exe","application/octet-stream",new byte[]{1})));assertThrows(com.johnny.hotel.exception.BusinessException.class,()->service.upload("IMAGE",new MockMultipartFile("file","x.jpg","image/jpeg",new byte[33])));image=service.upload("IMAGE",new MockMultipartFile("file","x.jpg","image/jpeg",new byte[]{(byte)0xff,(byte)0xd8,(byte)0xff}));model=service.upload("MODEL_3D",new MockMultipartFile("file","hotel.glb","model/gltf-binary",new byte[]{'g','l','T','F'}));var pc=page("en","English");pc.setSocialPreviewMediaId(image.getId());var p=service.create(pc);service.publish(p.getId());assertThrows(com.johnny.hotel.exception.BusinessException.class,()->service.archiveMedia(image.getId()));var sr=new CmsRequests.SceneWrite();sr.setName("Public model");sr.setLocale("en");sr.setSceneType("HOTEL");sr.setVisibility("PUBLIC");sr.setInteractionMode("PUBLIC_ORBIT_ONLY");sr.setMediaAssetId(model.getId());sr.setStatus("PUBLISHED");service.scene(null,sr);sr.setName("Internal model");sr.setVisibility("INTERNAL");sr.setInteractionMode("INTERNAL_INTERACTIVE");internal=service.scene(null,sr);var b=new CmsRequests.BindingWrite();b.setNodeKey("room-node-secret");b.setRoomId(jdbc.queryForObject("SELECT id FROM room ORDER BY id LIMIT 1",Long.class));service.bind(internal.getId(),b);mvc.perform(get("/api/public/site/scenes?locale=en")).andExpect(status().isOk()).andExpect(jsonPath("$.data[0].interactionMode").value("PUBLIC_ORBIT_ONLY")).andExpect(jsonPath("$.data[0].bindings").doesNotExist()).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("room-node-secret"))));mvc.perform(get("/api/admin/cms/scenes/{id}",internal.getId()).with(authentication(auth("MANAGER")))).andExpect(status().isOk()).andExpect(jsonPath("$.data.bindings[0].nodeKey").value("room-node-secret"));mvc.perform(get("/api/admin/cms/scenes/{id}",internal.getId()).with(authentication(auth("FINANCE")))).andExpect(status().isForbidden());}
 @Test@Order(4)void navigationPromotionLocationAndLocaleFallback()throws Exception{as("OWNER");var n=new CmsRequests.NavigationWrite();n.setLabel("Book");n.setLocale("zh-CN");n.setTargetType("EXTERNAL_URL");n.setTargetValue("javascript:alert(1)");n.setSortOrder(1);assertThrows(com.johnny.hotel.exception.BusinessException.class,()->service.navigation(null,n));n.setTargetType("BOOKING");n.setTargetValue(null);service.navigation(null,n);var pr=new CmsRequests.PromotionWrite();pr.setTitle("Offer");pr.setLocale("zh-CN");pr.setStatus("PUBLISHED");pr.setCoverMediaId(image.getId());pr.setGalleryMediaIds("["+image.getId()+"]");pr.setPricingPolicyId(Long.MAX_VALUE);assertThrows(com.johnny.hotel.exception.BusinessException.class,()->service.promotion(null,pr));pr.setPricingPolicyId(null);service.promotion(null,pr);var l=new CmsRequests.LocationWrite();l.setLocale("zh-CN");l.setHotelName("Hotel");l.setAddress("Address");l.setLatitude(new BigDecimal("31.2304"));l.setLongitude(new BigDecimal("121.4737"));l.setStatus("PUBLISHED");service.location(l);mvc.perform(get("/api/public/site/navigation?locale=fr")).andExpect(status().isOk()).andExpect(jsonPath("$.data[0].label").value("Book"));mvc.perform(get("/api/public/site/promotions?locale=fr")).andExpect(status().isOk()).andExpect(jsonPath("$.data[0].title").value("Offer")).andExpect(jsonPath("$.data[0].coverMediaUrl").value(image.getPublicUrl())).andExpect(jsonPath("$.data[0].galleryMediaUrls[0]").value(image.getPublicUrl()));mvc.perform(get("/api/public/site/location?locale=fr")).andExpect(status().isOk()).andExpect(jsonPath("$.data.hotelName").value("Hotel"));}
